'use strict';
const $=id=>document.getElementById(id), names=['SOOBIN','YEONJUN','BEOMGYU','TAEHYUN','HUENINGKAI'], colors=['#ded4f2','#d3e6ec','#f3d9e1','#e8e8c8','#d5e8dc','#f2ddc7','#d7dcf2','#ecd5ec'], chapters=['FIRST LIGHT','BLUE HOUR','DREAMSCAPE','STARRY NIGHT','PROMISE','GOLDEN HOUR','MOONLIT PATH','ETERNAL STARLIGHT'];
const words={zh:{gameGalleryBtn:'小卡冊',welcomeTitle:'準備好，和我們一起？',welcomeSub:'放慢腳步，解開下一個小謎題。',resumeLabel:'下一個舞台',levelsBtn:'關卡旅程 ↗',galleryBtn:'成員小卡 ↗',dailyTitle:'每日星光挑戰',dailySub:'每天一個小謎題，隨時慢慢玩。',journeyLabel:'旅程',rulePill:'每行・每列・每個色區各一位，相鄰格不可放。',inputGuide:'單擊 × · 雙擊放置 · 拖曳標記',undoLabel:'撤銷',redoLabel:'重做',resetLabel:'重來',hintLabel:'提示',asideTitle:'找到屬於<br>每顆星的位置。',asideText:'不用趕時間。每一個小小的發現，都讓你更接近答案。'},en:{gameGalleryBtn:'Cards',welcomeTitle:'A little moment, together.',welcomeSub:'Slow down. Your next little puzzle is waiting.',resumeLabel:'YOUR NEXT STAGE',levelsBtn:'Level journey ↗',galleryBtn:'Member cards ↗',dailyTitle:'Daily starlight challenge',dailySub:'One little puzzle, a fresh start every day.',journeyLabel:'Journey',rulePill:'One per row, column & color. No touching, even diagonally.',inputGuide:'Tap × · Double-tap to place · Drag to mark',undoLabel:'Undo',redoLabel:'Redo',resetLabel:'Restart',hintLabel:'Hint',asideTitle:'A perfect place<br>for every star.',asideText:'Take your time. Every little discovery brings you closer to the answer.'}};
let save={lang:'zh',done:{},sessions:{},dailyDone:{},last:0,equipped:[]},storageOK=true;try{let v=JSON.parse(localStorage.getItem('txt-starlight-v1'));if(v&&typeof v==='object')save={...save,...v};if(!['zh','en'].includes(save.lang))save.lang='zh';for(const k of ['done','sessions','dailyDone'])if(!save[k]||typeof save[k]!=='object')save[k]={};save.last=Math.min(LEVELS.length-1,Math.max(0,Number(save.last)||0))}catch(e){storageOK=false}let active=false,idx=0,puzzle=null,cells=[],elapsed=0,hints=0,gameState=null,daily=false,dailyDate='',won=false,lastTick=Date.now(),hinted=-1,toastTimer;
const tr=(z,e)=>save.lang==='zh'?z:e,cardPhoto=id=>'assets/'+Collection.cards[id].file,equipped=i=>Collection.choice(i%5,save.equipped,save.done),photo=i=>cardPhoto(equipped(i)),pad=n=>String(n).padStart(2,'0'),format=n=>pad(Math.floor(n/60))+':'+pad(n%60),dateKey=()=>new Date().getFullYear()+'-'+pad(new Date().getMonth()+1)+'-'+pad(new Date().getDate()),key=()=>daily?'daily-'+dailyDate:'level-'+idx;
function frame(i){const id=equipped(i),c=Collection.cards[id];return `<span class="faceFrame custom" style="--faceZoom:${c.zoom};--faceOrigin:${c.origin}"><img src="${cardPhoto(id)}" alt="${names[i%5]}" draggable="false"></span>`}
function persist(){try{localStorage.setItem('txt-starlight-v1',JSON.stringify(save))}catch(e){storageOK=false}}
function saveGame(){if(puzzle&&gameState&&!won)save.sessions[key()]={...gameState.serialize(),elapsed,hints};persist()}

function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2800)}
function setLang(){save.lang=save.lang==='zh'?'en':'zh';persist();translate();if(active){render();message()}}
function translate(){const en=save.lang==='en';document.documentElement.lang=en?'en':'zh-Hant';$('langBtn').textContent=en?'繁':'EN';for(const [id,value]of Object.entries(words[save.lang]))$(id).innerHTML=value;$('intro').innerHTML=tr('用一點推理，把五顆星星安放好。<br>屬於你與 TXT 的療癒解謎時光。','A little logic. Five shining stars.<br>Your quiet moment with TOMORROW X TOGETHER.');document.querySelector('.hero h1').innerHTML=tr('每一個你，<br>都有專屬位置','Every star.<br>A place to shine.')+'<span>Find your place, together.</span>';$('homeBtn').setAttribute('aria-label',tr('首頁','Home'));$('helpBtn').setAttribute('aria-label',tr('玩法說明','How to play'));$('closeModal').setAttribute('aria-label',tr('關閉','Close'));$('fanNote').innerHTML=tr('UNOFFICIAL FAN GAME · 非官方粉絲遊戲','UNOFFICIAL FAN GAME · MADE FOR FANS')+'<br>'+tr('相片','Photos')+' © BIGHIT MUSIC / HYBE · <a href="https://ibighit.com/legacy/txt/minisode-3-en.html" target="_blank" rel="noopener">'+tr('相片來源','Photo source')+'</a>';updateHome()}
function updateHome(){const total=Collection.completedCount(save.done);$('resumeLevel').innerHTML=pad(save.last+1)+' <small>/ '+LEVELS.length+'</small>';$('completedText').textContent=tr('已完成 '+total+' / '+LEVELS.length+' 關',total+' / '+LEVELS.length+' stages complete');$('progressPct').textContent=Math.round(total/LEVELS.length*100)+'%';$('progressFill').style.width=total/LEVELS.length*100+'%';$('playBtn').innerHTML=tr(save.sessions['level-'+save.last]?'繼續遊戲':'進入遊戲',save.sessions['level-'+save.last]?'Continue playing':'Start playing')+' <span>↗</span>';$('dailySub').textContent=save.dailyDone[dateKey()]?tr('今日已完成 ✓ 可以再次挑戰。','Completed today ✓ Play again anytime.'):words[save.lang].dailySub}
function modal(html){$('modalContent').innerHTML=html;if(!$('modal').open)$('modal').showModal();lastTick=Date.now()}
function closeModal(){$('modal').close();lastTick=Date.now()}
function help(){modal('<div class="modalEyebrow">MEOWDOKU-STYLE LOGIC</div><h2>'+tr('同一套推理玩法，換上 TXT。','The same logic. Your five stars.')+'</h2><ul class="ruleList"><li><b>01</b>'+tr('每行、每列、每個顏色區域，各放一位成員。','Exactly one member in every row, column and colored region.')+'</li><li><b>02</b>'+tr('成員不可相鄰，包括緊貼嘅斜角；遠距離斜線不受限制。','Members cannot touch, including corners. Distant diagonals are allowed.')+'</li><li><b>03</b>'+tr('點一下畫 × 或取消 ×；快速點兩下先放置成員。拖過多格可以連續標記或清除。','Tap once to add or remove ×. Double-tap to place a member. Drag across cells to mark or erase several at once.')+'</li><li><b>04</b>'+tr('放錯位置扣一顆心，三顆心用完就要重試。正確落子會固定，唔可以移除。','Wrong placements cost a heart. Three mistakes end the attempt. Correct placements stay locked.')+'</li></ul><p>'+tr('正確落子後唔會自動畫 ×。唔使揀成員身份：相片會按色區自動顯示。撤銷只影響你嘅 × 筆記，唔會退還生命或移走正確成員。','No automatic × marks appear after a correct placement. No need to choose identities: each region assigns a photo. Undo changes your × notes; it does not restore hearts or remove accepted members.')+'</p><button class="primary" id="gotIt">'+tr('明白，開始解謎','Got it, let’s play')+' <span>↗</span></button>');$('gotIt').onclick=closeModal}

function start(i,isDaily=false,forDate=dateKey()){cancelPending();if(active)saveGame();idx=Math.min(LEVELS.length-1,Math.max(0,i));daily=isDaily;dailyDate=forDate;puzzle=LEVELS[idx];active=true;won=false;hinted=-1;let saved=save.sessions[key()];gameState=new MeowGame(puzzle,saved);elapsed=Math.max(0,Number(saved?.elapsed)||0);hints=Math.max(0,Number(saved?.hints)||0);if(!daily)save.last=idx;persist();$('home').classList.add('hidden');$('game').classList.remove('hidden');closeModal();lastTick=Date.now();render();message();window.scrollTo({top:0,behavior:'instant'});if(gameState.lost)showLoss();else if(gameState.won)checkWin();if(!storageOK)toast(tr('瀏覽器未能儲存，離開後進度可能消失。','Browser storage unavailable; progress may not persist.'))}

function home(){cancelPending();if(active)saveGame();active=false;$('game').classList.add('hidden');$('home').classList.remove('hidden');closeModal();updateHome();window.scrollTo({top:0,behavior:'instant'})}
function selections(){return gameState.placed.map((v,i)=>v?i:-1).filter(i=>i>=0)}

function badCells(){return new Set(gameState.lastError>=0?[gameState.lastError]:[])}

function render(){if(!puzzle)return;const focusIndex=document.activeElement?.closest('[data-i]')?.dataset.i;const n=puzzle.n,chapter=Math.floor(idx/15),selected=selections(),bad=badCells();cells=gameState.placed.map((v,i)=>v?1:gameState.notes[i]?2:0);$('stageLabel').textContent=daily?tr('每日挑戰','DAILY CHALLENGE'):chapters[chapter];$('gameEyebrow').textContent=daily?'DAILY · '+dailyDate:'CHAPTER '+pad(chapter+1)+' · '+chapters[chapter];$('levelHeading').textContent=daily?tr('每日星光','Daily starlight'):tr('第 '+pad(idx+1)+' 關','Stage '+pad(idx+1));$('timer').textContent=format(elapsed);$('placedText').textContent=tr(selected.length+' / '+n+' 位已就位',selected.length+' / '+n+' stars placed');$('sizeText').textContent=n+' × '+n;$('hearts').innerHTML=Array.from({length:3},(_,i)=>'<span class="'+(i<gameState.hearts?'':'emptyHeart')+'">♥</span>').join('');$('hearts').setAttribute('aria-label',tr('剩餘 '+gameState.hearts+' 顆心',gameState.hearts+' hearts remaining'));$('undoBtn').disabled=!gameState.history.length||gameState.inactive;$('redoBtn').disabled=!gameState.future.length||gameState.inactive;$('hintBtn').disabled=gameState.inactive;$('board').style.gridTemplateColumns=`repeat(${n},1fr)`;$('board').style.gridTemplateRows=`repeat(${n},1fr)`;$('board').setAttribute('aria-label',tr(n+'乘'+n+' 解謎棋盤',n+' by '+n+' puzzle board'));
$('board').innerHTML=cells.map((v,i)=>{const g=puzzle.regions[i],r=Math.floor(i/n),c=i%n;let borders='';for(const [side,j,edge]of [['t',i-n,r===0],['b',i+n,r===n-1],['l',i-1,c===0],['r',i+1,c===n-1]]){if(edge||puzzle.regions[j]!==g)borders+=`--bw${side}:2px;--b${side}:#fff;`}return `<button class="cell${bad.has(i)?' bad':''}${hinted===i?' hinted':''}${v===1?' settled':''}" style="--bg:${colors[g]};${borders}" data-i="${i}" aria-label="${tr('第'+(r+1)+'行 第'+(c+1)+'列 色區'+(g+1),'Row '+(r+1)+', column '+(c+1)+', region '+(g+1))}${v===1?', '+names[g%5]:v===2?tr('，已排除',', marked empty'):''}" aria-pressed="${v===1}"><span class="regionNum">${g+1}</span>${v===1?frame(g):v===2?'<span class="mark">×</span>':''}</button>`}).join('');if(focusIndex!==undefined)$('board').querySelector('[data-i="'+focusIndex+'"]')?.focus({preventScroll:true});}
function message(text,isWarning=false){$('hintBox').textContent=text||tr('單擊畫 ×，雙擊放置成員；拖曳可連續畫 ×。','Tap once for ×. Double-tap to place. Drag to mark several.');$('hintBox').classList.toggle('warning',isWarning)}


function act(i){if(won||!active||gameState.inactive)return;hinted=-1;const result=gameState.place(i);if(result==='locked'){message(tr('呢位成員已經搵到正確位置，唔需要移動。','This member is correctly placed and stays locked.'));return}render();saveGame();if(result==='wrong'){message(tr('呢格唔係正確位置，扣一顆心。剩返 '+gameState.hearts+' 顆。','That is not the correct location. One heart lost; '+gameState.hearts+' remaining.'),true);if(gameState.lost)showLoss();return}message(tr('位置正確！繼續找出下一位。','Correct! Find the next member.'));checkWin()}

function checkWin(){if(won||!gameState.won)return;won=true;delete save.sessions[key()];const oldCards=Collection.unlocked(save.done);const previous=daily?save.dailyDone[dailyDate||dateKey()]:save.done[idx];const result={time:elapsed,hints};if(daily)save.dailyDone[dailyDate||dateKey()]=!previous||elapsed<previous.time?result:previous;else{save.done[idx]=!previous||elapsed<previous.time?result:previous;save.last=Math.min(LEVELS.length-1,idx+1)}persist();render();const count=Collection.unlocked(save.done);modal('<div class="win"><div class="winStar">✦</div><div class="modalEyebrow">EVERY STAR IN ITS PLACE</div><h2>'+tr('我哋，找到彼此了。','Perfectly together.')+'</h2><p>'+tr('你為每顆星，搵到最啱嘅位置。','You found a perfect place for every star.')+'</p><div class="winFaces">'+names.map((n,i)=>frame(i)).join('')+'</div><div class="winStats"><div><span>'+tr('完成時間','TIME')+'</span><strong>'+format(elapsed)+'</strong></div><div><span>'+tr('使用提示','HINTS')+'</span><strong>'+hints+'</strong></div></div>'+(!daily&&count>oldCards?'<p>'+tr('✧ 成員小卡已解鎖：','✧ Member card unlocked: ')+names[Collection.cards[count-1].member]+' · '+Collection.cards[count-1].album+'</p>':'')+'<button id="nextBtn" class="primary">'+tr(daily?'返回首頁':idx===LEVELS.length-1?'完成旅程':'下一個舞台',daily?'Back home':idx===LEVELS.length-1?'Journey complete':'Next stage')+' <span>↗</span></button><button id="winHome" class="secondary">'+tr('返回首頁','Back home')+'</button></div>');$('nextBtn').onclick=()=>daily||idx===LEVELS.length-1?home():start(idx+1);$('winHome').onclick=home}
function hint(){cancelPending();if(won||gameState.inactive)return;const solution=gameState.answer;let target=-1,reason='';const n=puzzle.n,blocked=gameState.blocked();for(let r=0;r<n;r++){if(solution.some(i=>Math.floor(i/n)===r&&gameState.placed[i]))continue;const opts=[];for(let c=0;c<n;c++){const i=r*n+c;if(!blocked[i])opts.push(i)}if(opts.length===1){target=opts[0];reason=tr('第 '+(r+1)+' 行只剩呢一格符合規則。','Only this cell remains available in row '+(r+1)+'.');break}}if(target<0){target=solution.find(i=>!gameState.placed[i]);reason=tr('完整盤面推演：第 '+(Math.floor(target/n)+1)+' 行、第 '+(target%n+1)+' 列係正確位置。','Full-board deduction: row '+(Math.floor(target/n)+1)+', column '+(target%n+1)+' is correct.')}if(target===undefined)return;gameState.place(target);hinted=target;hints++;render();message(reason);saveGame();checkWin()}

function levels(){let html='<div class="modalEyebrow">YOUR STARLIGHT JOURNEY</div><h2>'+tr('自由揀關，按你嘅步伐。','Your journey. Your choice.')+'</h2><p>'+tr(LEVELS.length+' 個唯一解關卡，全部自由選擇。完成不同關卡，逐步解鎖成員小卡。',LEVELS.length+' unique puzzles, all freely selectable. Complete different stages to unlock member cards.')+'</p>';for(let chapter=0;chapter<chapters.length;chapter++){const first=chapter*15,last=Math.min(first+15,LEVELS.length),n=LEVELS[first].n;html+='<div class="chapterName">'+pad(chapter+1)+' · '+chapters[chapter]+' · '+n+' × '+n+'</div><div class="levelGrid">';for(let j=first;j<last;j++)html+=`<button data-level="${j}" aria-label="${tr('第 '+(j+1)+' 關','Stage '+(j+1))}${save.done[j]?tr('，已完成',', completed'):''}" class="${save.done[j]?'done':''} ${j===save.last?'current':''}">${pad(j+1)}</button>`;html+='</div>'}modal(html);$('modalContent').querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>start(Number(b.dataset.level)))}
function portrait(i,fromGallery=false){modal('<div class="modalEyebrow">OUR FIVE SHINING STARS</div><h2>'+names[i]+'</h2><img class="portraitLarge" src="'+photo(i)+'" alt="'+names[i]+'"><p>'+tr('相片來源：BIGHIT MUSIC 官方概念照《minisode 3: TOMORROW》。','Photo: BIGHIT MUSIC · minisode 3: TOMORROW official concept photos.')+'</p>'+(fromGallery?'<button class="secondary" id="galleryBack">'+tr('← 返回小卡冊','← Back to cards')+'</button>':''));if(fromGallery)$('galleryBack').onclick=gallery}
let galleryFilter=-1;
function gallery(){const count=Collection.unlocked(save.done),visible=Collection.cards.filter(c=>galleryFilter<0||c.member===galleryFilter);modal('<div class="modalEyebrow">FORTY MOMENTS, FIVE STARS</div><h2>'+tr('你嘅成員小卡冊','Your member card collection')+'</h2><p>'+tr('40 張不同真人相片，每位成員 8 張。首 20 張按完成關卡數解鎖；之後累計完成 25、30…120 個不同關卡，每 5 關解鎖一張。可將已解鎖小卡設為棋子相片。','40 different photos, eight per member. The first 20 unlock one per distinct stage completed; then collect one at 25, 30…120 completed stages. Equip unlocked cards as member photos.')+'</p><div class="filterChips"><button data-filter="-1" class="'+(galleryFilter<0?'selected':'')+'">'+tr('全部','All')+'</button>'+names.map((n,i)=>'<button data-filter="'+i+'" class="'+(galleryFilter===i?'selected':'')+'">'+n+'</button>').join('')+'</div><div class="collectionCount">'+count+' / '+Collection.cards.length+' '+tr('已收藏','collected')+'</div><div class="galleryGrid">'+visible.map(c=>`<button class="photoCard ${c.id>=count?'locked':''}" data-card="${c.id}" ${c.id>=count?'disabled':''}><img src="${cardPhoto(c.id)}" alt="${names[c.member]} ${c.album}" loading="lazy"><span>${names[c.member]}</span><small>${c.album} · ${String(c.id+1).padStart(2,'0')}</small><b>${c.id<count?(equipped(c.member)===c.id?tr('使用中 ✓','Equipped ✓'):tr('查看小卡','View card')):tr('累計完成 '+Collection.requiredCount(c.id)+' 個不同關卡解鎖','Complete '+Collection.requiredCount(c.id)+' different stages')}</b></button>`).join('')+'</div>');$('modalContent').querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>showCard(Number(b.dataset.card)));$('modalContent').querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{galleryFilter=Number(b.dataset.filter);gallery()})}
function showCard(id){if(!Collection.canEquip(id,save.done))return;const c=Collection.cards[id],count=Collection.unlocked(save.done),isEquipped=equipped(c.member)===id;modal('<div class="modalEyebrow">'+c.album+' · '+String(id+1).padStart(2,'0')+' / '+Collection.cards.length+'</div><h2>'+names[c.member]+'</h2><img class="portraitLarge" src="'+cardPhoto(id)+'" alt="'+names[c.member]+' '+c.album+'"><div class="cardPager"><button id="prevCard" '+(id===0?'disabled':'')+'>← '+tr('上一張','Previous')+'</button><button id="nextCard" '+(id>=count-1?'disabled':'')+'>'+tr('下一張','Next')+' →</button></div><button class="primary" id="equipCard" '+(isEquipped?'disabled':'')+'>'+tr(isEquipped?'已設為棋子相片 ✓':'設為棋子相片',isEquipped?'Equipped as member photo ✓':'Use as member photo')+'</button><button class="secondary" id="galleryBack">'+tr('← 返回小卡冊','← Back to cards')+'</button>');$('prevCard').onclick=()=>showCard(id-1);$('nextCard').onclick=()=>showCard(id+1);$('galleryBack').onclick=gallery;$('equipCard').onclick=()=>{if(!Collection.canEquip(id,save.done))return;if(!Array.isArray(save.equipped))save.equipped=[];save.equipped[c.member]=id;persist();renderMembers();if(active)render();showCard(id);toast(tr('已更新 '+names[c.member]+' 嘅棋子相片。',names[c.member]+' photo updated.'))}}
function renderMembers(){
$('memberFaces').innerHTML=names.map((n,i)=>`<button data-person="${i}" aria-label="${n}">${frame(i)}<span>${n}</span></button>`).join('');$('memberFaces').querySelectorAll('button').forEach(b=>b.onclick=()=>portrait(Number(b.dataset.person)));$('sideMembers').innerHTML=names.map((n,i)=>`<div class="sideMember">${frame(i)}<span>${n}</span></div>`).join('');
}
renderMembers();
$('playBtn').onclick=()=>start(save.last);$('homeBtn').onclick=home;$('backBtn').onclick=home;$('langBtn').onclick=setLang;$('levelsBtn').onclick=levels;$('galleryBtn').onclick=gallery;$('dailyBtn').onclick=()=>{let hash=[...dateKey()].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,0);start(15+hash%(LEVELS.length-15),true)};$('helpBtn').onclick=help;$('gameHelp').onclick=help;$('closeModal').onclick=closeModal;$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});$('modal').addEventListener('close',()=>lastTick=Date.now());$('gameGalleryBtn').onclick=()=>{flushPending();gallery()};$('undoBtn').onclick=()=>{flushPending();if(gameState.undo()){render();message();saveGame()}};$('redoBtn').onclick=()=>{flushPending();if(gameState.redo()){render();message();saveGame()}};$('hintBtn').onclick=hint;$('resetBtn').onclick=()=>{cancelPending();if(won)return;modal('<h2>'+tr('重新開始呢一關？','Restart this stage?')+'</h2><p>'+tr('重新開始會恢復三顆心，清空本關落子、標記同計時；已完成關卡同小卡會保留。','Restart restores three hearts and resets placements, marks and timer. Completed stages and cards are kept.')+'</p><button class="primary" id="confirmReset">'+tr('重新開始','Restart')+'</button><button class="secondary" id="cancelReset">'+tr('繼續解謎','Keep playing')+'</button>');$('confirmReset').onclick=()=>{delete save.sessions[key()];active=false;start(idx,daily,dailyDate)};$('cancelReset').onclick=closeModal};

function showLoss(){modal('<div class="win"><div class="winStar" style="color:#cb788c">♡</div><div class="modalEyebrow">TAKE A BREATH. TRY AGAIN.</div><h2>'+tr('三顆心用完喇。','Out of hearts.')+'</h2><p>'+tr('今次挑戰結束。再試一次，先用 × 排除唔可能嘅格，再雙擊落子。','This attempt has ended. Try again: mark impossible cells with × before double-tapping to place.')+'</p><button class="primary" id="retryBtn">'+tr('恢復三顆心，重新挑戰','Try again with three hearts')+' <span>↗</span></button><button class="secondary" id="lossHome">'+tr('返回首頁','Back home')+'</button></div>');$('retryBtn').onclick=()=>{delete save.sessions[key()];active=false;start(idx,daily,dailyDate)};$('lossHome').onclick=home}
let pendingTap=null,gesture=null;
function cancelPending(){if(pendingTap)clearTimeout(pendingTap.timer);pendingTap=null;gesture=null}
function flushPending(){if(!pendingTap)return;const i=pendingTap.i;clearTimeout(pendingTap.timer);pendingTap=null;markOne(i)}
function markOne(i){if(!active||won||gameState.inactive)return;if(gameState.placed[i]){message(tr('正確位置已固定，唔可以移除。','Correct placements stay locked.'));return}gameState.mark([i],!gameState.notes[i]);hinted=-1;render();message();saveGame()}
function tap(i){if(!active||won||gameState.inactive)return;const now=Date.now();if(pendingTap&&pendingTap.i===i&&now-pendingTap.time<=340){clearTimeout(pendingTap.timer);pendingTap=null;act(i);return}flushPending();pendingTap={i,time:now,timer:setTimeout(flushPending,340)}}
const board=$('board');
board.addEventListener('pointerdown',e=>{if(e.button!==0||!active||won||gameState.inactive||gesture)return;const b=e.target.closest('[data-i]');if(!b)return;const i=Number(b.dataset.i);gesture={id:e.pointerId,start:i,last:i,x:e.clientX,y:e.clientY,drag:false,recorded:false,value:!gameState.notes[i]};board.setPointerCapture(e.pointerId)});
function paintIndices(indices){if(!gesture)return;const valid=indices;if(gameState.mark(valid,gesture.value,!gesture.recorded)){gesture.recorded=true;hinted=-1;render();message(tr(gesture.value?'拖曳標記中：放開即可完成。':'拖曳清除中：放開即可完成。',gesture.value?'Marking cells — release to finish.':'Erasing notes — release to finish.'));saveGame()}}
board.addEventListener('pointermove',e=>{if(!gesture||gesture.id!==e.pointerId)return;if(!gesture.drag&&Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y)<9)return;if(!gesture.drag){flushPending();gesture.drag=true;paintIndices([gesture.start])}const rect=board.getBoundingClientRect(),x=Math.floor((e.clientX-rect.left)/rect.width*puzzle.n),y=Math.floor((e.clientY-rect.top)/rect.height*puzzle.n);if(x<0||x>=puzzle.n||y<0||y>=puzzle.n)return;const i=y*puzzle.n+x;if(i===gesture.last)return;const r=Math.floor(gesture.last/puzzle.n),c=gesture.last%puzzle.n,steps=Math.max(Math.abs(y-r),Math.abs(x-c)),indices=[];for(let k=1;k<=steps;k++)indices.push(Math.round(r+(y-r)*k/steps)*puzzle.n+Math.round(c+(x-c)*k/steps));gesture.last=i;paintIndices(indices)});
board.addEventListener('pointerup',e=>{if(!gesture||gesture.id!==e.pointerId)return;const g=gesture;gesture=null;if(board.hasPointerCapture(e.pointerId))board.releasePointerCapture(e.pointerId);if(g.drag){saveGame();message();return}tap(g.start)});
board.addEventListener('pointercancel',()=>{gesture=null;saveGame()});
board.addEventListener('contextmenu',e=>{const b=e.target.closest('[data-i]');if(!b)return;e.preventDefault();cancelPending();act(Number(b.dataset.i))});
board.addEventListener('keydown',e=>{const b=e.target.closest('[data-i]');if(!b)return;const i=Number(b.dataset.i),n=puzzle.n;if(['Enter',' '].includes(e.key)){e.preventDefault();if(!e.repeat)tap(i);return}const delta={ArrowUp:-n,ArrowDown:n,ArrowLeft:-1,ArrowRight:1}[e.key];if(delta){e.preventDefault();flushPending();const j=i+delta;if(j>=0&&j<n*n&&!(e.key==='ArrowLeft'&&i%n===0)&&!(e.key==='ArrowRight'&&i%n===n-1))board.querySelector('[data-i="'+j+'"]').focus()}});

setInterval(()=>{const now=Date.now(),delta=Math.floor((now-lastTick)/1000);if(delta<1)return;lastTick+=delta*1000;if(active&&!won&&!gameState.lost&&!document.hidden&&!$('modal').open){elapsed+=Math.min(delta,2);$('timer').textContent=format(elapsed);if(elapsed%5===0)saveGame()}},500);document.addEventListener('visibilitychange',()=>{lastTick=Date.now();if(document.hidden)saveGame()});window.addEventListener('pagehide',()=>{flushPending();saveGame()});translate();
